def deco(f):
    def inner(*a, **k):
        return f(*a, **k)
    return inner

@deco
def greet():
    "Say hi"

print(greet.__name__)

def tag(name):
    print("factory", name)
    def deco(f):
        print("decorate", name)
        return f
    return deco

@tag("a")
@tag("b")
def f(): pass

